def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "0\n"

    n, m, k = map(int, lines[0].split())

    # Edge case: single city needs 0 edges
    if n == 1:
        return "0\n"

    edges = []
    for i in range(m):
        parts = list(map(int, lines[1 + i].split()))
        u, v, w = parts[0], parts[1], parts[2]
        edges.append((w, u, v, i + 1))

    capital_edges = []
    other_edges = []

    for w, u, v, idx in edges:
        if u == 1 or v == 1:
            capital_edges.append((w, u, v, idx))
        else:
            other_edges.append((w, u, v, idx))

    capital_edges.sort()
    other_edges.sort()

    parent = list(range(n + 1))

    def find(x):
        if parent[x] == x:
            return x
        parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rootx = find(x)
        rooty = find(y)
        if rootx != rooty:
            parent[rootx] = rooty
            return True
        return False

    result = []

    # Phase 1: Select up to k capital edges
    capital_count = 0
    for w, u, v, idx in capital_edges:
        if capital_count < k and union(u, v):
            result.append(idx)
            capital_count += 1
        if capital_count == k:
            break

    # Phase 2: Add other edges to complete MST
    for w, u, v, idx in other_edges:
        if union(u, v):
            result.append(idx)

    # Count final capital edges in result
    capital_count_final = sum(1 for w, u, v, idx in result 
                              if u == 1 or v == 1)

    # Check connectivity
    root = find(1)
    for i in range(2, n + 1):
        if find(i) != root:
            return "-1"

    # Check if we have exactly k capital edges
    if capital_count_final != k:
        return "-1"

    result.sort()
    return str(len(result)) + "\n" + " ".join(map(str, result)) + "\n"
