def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m, k = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        v, u = map(int, lines[i].split())
        adj[v].append(u)
        adj[u].append(v)

    # Minimum path length required (ceiling of n/k)
    min_path_len = (n + k - 1) // k

    # Try to find k vertex-disjoint cycles
    result_cycles = []
    used_reps = set()
    all_used = set()

    def find_cycle_with_rep(start):
        global result_cycles

        # Find all nodes reachable from start
        parent = {start: None}
        depth = {start: 0}
        visited = {start}
        stack = [start]

        while stack:
            u = stack[-1]
            found_next = False

            for v in adj[u]:
                if v == parent[u]:
                    continue
                if v not in visited:
                    visited.add(v)
                    parent[v] = u
                    depth[v] = depth[u] + 1
                    stack.append(v)
                    found_next = True
                    break

            if not found_next:
                stack.pop()

        # Look for back-edges (v is already visited, v != parent[u])
        for u in list(visited):
            if u in parent:
                for v in adj[u]:
                    if v in visited and v != parent.get(u):
                        # This is a back-edge
                        cycle_len = depth[u] - depth[v] + 1
                        if cycle_len >= 3 and cycle_len % 3 != 0:
                            # Extract cycle
                            path = [v]
                            curr = u
                            while curr != v:
                                path.append(curr)
                                curr = parent[curr]
                            path.reverse()
                            rep = v

                            if rep not in used_reps:
                                result_cycles.append(path)
                                used_reps.add(rep)
                                all_used.update(path)
                                return True
                        # Try other back-edges
                        break

        return False

    # DFS to find cycles
    for start in range(1, n + 1):
        if start in all_used and result_cycles:
            if len(result_cycles) >= k:
                break
        if result_cycles and len(result_cycles) >= k:
            break

        # Check if there are unvisited nodes we can start from
        unvisited = [i for i in range(1, n + 1) if i not in all_used]
        if not unvisited and result_cycles and len(result_cycles) >= k:
            break

        if not result_cycles or len(result_cycles) < k:
            if unvisited:
                if find_cycle_with_rep(unvisited[0]):
                    continue
            else:
                # Try all starts even if some nodes used
                find_cycle_with_rep(start)
                if not result_cycles or len(result_cycles) < k:
                    break
        else:
            if len(result_cycles) >= k:
                break

    if len(result_cycles) >= k:
        output = ["CYCLES"]
        for cycle in result_cycles[:k]:
            output.append(str(len(cycle)))
            output.append(" ".join(map(str, cycle)))
        return "\n".join(output)

    # Try to find a path of length >= min_path_len
    path_found = None

    for start in range(1, n + 1):
        visited = set([start])
        path = [start]
        stack = [start]
        parent = {start: None}

        while stack:
            u = stack[-1]
            found = False
            for v in adj[u]:
                if v not in visited:
                    visited.add(v)
                    path.append(v)
                    parent[v] = u
                    stack.append(v)
                    found = True
                    break
            if not found:
                stack.pop()
                if len(path) > 1:
                    path.pop()

        if len(path) >= min_path_len:
            path_found = path
            break

    if path_found:
        return "PATH\n" + str(len(path_found)) + "\n" + " ".join(map(str, path_found))
    else:
        return "-1"
