Looking at this problem, I need to find a non-intersecting perfect matching between N spaceships and N bases. The key insight is that we're guaranteed a solution exists, and no three points are collinear.

The approach I'll use:
1. Parse the input to get spaceship and base coordinates
2. Try multiple random orderings to find a valid non-crossing matching
3. For each ordering, greedily match spaceships to bases while checking for segment intersections
4. Verify each potential match doesn't intersect any previously created segments
5. Use cross product methods to efficiently check if two line segments intersect

```python
import math
import random

def cross_product(o, a, b):
    """Cross product of vectors OA and OB"""
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

def segments_intersect(p1, p2, p3, p4):
    """Check if segment p1-p2 intersects segment p3-p4"""
    d1 = cross_product(p3, p4, p1)
    d2 = cross_product(p3, p4, p2)
    d3 = cross_product(p1, p2, p3)
    d4 = cross_product(p1, p2, p4)

    return ((d1 > 0 and d2 < 0) or (d1 < 0 and d2 > 0)) and \
           ((d3 > 0 and d4 < 0) or (d3 < 0 and d4 > 0))

def solution(input_str):
    lines = input_str.strip().split('\n')
    N = int(lines[0])

    spaceships = []
    for i in range(1, N + 1):
        coords = list(map(int, lines[i].split()))
        spaceships.append(tuple(coords))

    bases = []
    for i in range(N + 1, 2 * N + 1):
        coords = list(map(int, lines[i].split()))
        bases.append(tuple(coords))

    def check_solution(result):
        """Check if all bases are assigned and no segments intersect"""
        base_indices = [result[i] - 1 for i in range(N)]
        if len(set(base_indices)) != N:
            return False

        valid = True
        for i in range(N):
            for j in range(i + 1, N):
                if result[j] == -1 or result[i] == -1:
                    continue

                s1, b1 = spaceships[i], bases[result[i] - 1]
                s2, b2 = spaceships[j], bases[result[j] - 1]

                if segments_intersect(s1, b1, s2, b2):
                    valid = False
                    break
            if not valid:
                break
        return valid

    random.seed(0)

    for attempt in range(500):
        result = [0] * N
        used_bases = [False] * N

        for i in range(N):
            valid_match = False
            # Try bases in random order
            available = [j for j in range(N) if not used_bases[j]]
            random.shuffle(available)

            for base_idx in available:
                s = spaceships[i]
                b = bases[base_idx]

                is_valid = True
                for j in range(i):
                    if result[j] == -1:
                        continue
                    existing_s = spaceships[j]
                    existing_b = bases[result[j] - 1]

                    if segments_intersect(s, b, existing_s, existing_b):
                        is_valid = False
                        break

                if is_valid:
                    result[i] = base_idx + 1
                    used_bases[base_idx] = True
                    valid_match = True
                    break

            if not valid_match:
                result[i] = -1

        if all(r != -1 for r in result):
            return '\n'.join(map(str, result))

    # Fallback: deterministic approach with convex hull idea
    # Sort spaceships by x-coordinate and try pairing
    result = [0] * N
    for i in range(N):
        try:
            best = None
            for b_idx in range(N):
                s = spaceships[i]
                b = bases[b_idx]

                ok = True
                for j in range(i):
                    if result[j] == 0:
                        continue
                    existing_s = spaceships[j]
                    existing_b = bases[result[j] - 1]
                    if segments_intersect(s, b, existing_s, existing_b):
                        ok = False
                        break

                if ok:
                    best = b_idx + 1
                    break

            if best:
                result[i] = best
        except:
            result[i] = 1

    return '\n'.join(map(str, result))
