    n = int(lines[0])
    points = []
    for i in range(1, n + 1):
        coords = list(map(int, lines[i].split()))
        points.append(tuple(coords))

    # Shuffle points for better numerical stability
    random.shuffle(points)

    def dist_sq(a, b):
        return (a[0]-b[0])**2 + (a[1]-b[1])**2 + (a[2]-b[2])**2

    def dist(a, b):
        return math.sqrt(dist_sq(a, b))

    def compute_sphere(R):
        """Compute sphere from boundary points R (max 4 points)"""
        if len(R) == 0:
            return (0.0, (0.0, 0.0, 0.0))
        elif len(R) == 1:
            return (0.0, R[0])
        elif len(R) == 2:
            c0 = (R[0][0] + R[1][0]) / 2.0
            c1 = (R[0][1] + R[1][1]) / 2.0
            c2 = (R[0][2] + R[1][2]) / 2.0
            r = dist(R[0], R[1]) / 2.0
            return (r, (c0, c1, c2))
        elif len(R) == 3:
            p1, p2, p3 = R
            a1 = p1[0] - p2[0]
            b1 = p1[1] - p2[1]
            c1 = p1[2] - p2[2]
            k1 = dist_sq(p1, p2) / 2.0 + (dist_sq(p2, (0,0,0)) - dist_sq(p1, (0,0,0))) / 2.0

            a2 = p1[0] - p3[0]
            b2 = p1[1] - p3[1]
            c2 = p1[2] - p3[2]
            k2 = dist_sq(p1, p3) / 2.0 + (dist_sq(p3, (0,0,0)) - dist_sq(p1, (0,0,0))) / 2.0

            a3 = p2[0] - p3[0]
            b3 = p2[1] - p3[1]
            c3 = p2[2] - p3[2]
            k3 = dist_sq(p2, p3) / 2.0 + (dist_sq(p3, (0,0,0)) - dist_sq(p2, (0,0,0))) / 2.0

            M = [[a1, b1, c1, float(k1)],
                 [a2, b2, c2, float(k2)],
                 [a3, b3, c3, float(k3)]]

            for i in range(3):
                max_j = i
                for j in range(i+1, 3):
                    if abs(M[j][i]) > abs(M[max_j][i]):
                        max_j = j
                M[i], M[max_j] = M[max_j], M[i]

                if abs(M[i][i]) < 1e-12:
                    centroid = ((p1[0]+p2[0]+p3[0])/3.0,
                               (p1[1]+p2[1]+p3[1])/3.0,
                               (p1[2]+p2[2]+p3[2])/3.0)
                    return (dist(p1, centroid), centroid)

                for j in range(i+1, 3):
                    f = M[j][i] / M[i][i]
                    for c in range(3, 4):
                        M[j][c] -= f * M[i][c]

            x = [M[i][3] / M[i][i] for i in range(3)]
            center = (x[0], x[1], x[2])
            return (dist(p1, center), center)
        else:
            # 4 points
            p1, p2, p3, p4 = R
            a1 = p2[0] - p1[0]
            b1 = p2[1] - p1[1]
            c1 = p2[2] - p1[2]
            d1 = dist_sq(p1, p2)

            a2 = p3[0] - p1[0]
            b2 = p3[1] - p1[1]
            c2 = p3[2] - p1[2]
            d2 = dist_sq(p1, p3)

            a3 = p4[0] - p1[0]
            b3 = p4[1] - p1[1]
            c3 = p4[2] - p1[2]
            d3 = dist_sq(p1, p4)

            M = [
                [2*a1, 2*b1, 2*c1, (dist_sq(p1, p2) - dist_sq(p1, (0,0,0)))/2],
                [2*a2, 2*b2, 2*c2, (dist_sq(p1, p3) - dist_sq(p1, (0,0,0)))/2],
                [2*a3, 2*b3, 2*c3, (dist_sq(p1, p4) - dist_sq(p1, (0,0,0)))/2]
            ]
            M[0][3], M[1][3], M[2][3] = M[0][3]*2, M[1][3]*2, M[2][3]*2

            for i in range(3):
                max_j = i
                for j in range(i+1, 3):
                    if abs(M[j][i]) > abs(M[max_j][i]):
                        max_j = j
                M[i], M[max_j] = M[max_j], M[i]

                if abs(M[i][i]) < 1e-12:
                    return (0.0, ((p1[0]+p2[0]+p3[0]+p4[0])/4.0,
                                  (p1[1]+p2[1]+p3[1]+p4[1])/4.0,
                                  (p1[2]+p2[2]+p3[2]+p4[2])/4.0))

                for j in range(i+1, 3):
                    f = M[j][i] / M[i][i]
                    for c in range(3, 4):
                        M[j][c] -= f * M[i][c]

            x = [M[i][3] / M[i][i] for i in range(3)]
            center = (x[0], x[1], x[2])
            return (dist(p1, center), center)

    def welzl(points, R):
        if not points or len(R) == 4:
            return compute_sphere(R)

        p = points[-1]
        points.pop()
        d = welzl(points, R)

        if dist_sq(p, d[1]) <= d[0]**2 + 1e-12:
            return d
        else:
            return welzl(points, R + [p])

    d = welzl(points[:], [])

    return "{:.10f} {:.10f} {:.10f}\n".format(d[1][0], d[1][1], d[1][2])
