        match = self.match_number()
        if not match:
            raise ValueError("Expected number")

        num_val, num_digits = match

        if self.pos < self.length and self.s[self.pos] == '-':
            self.pos += 1  # consume '-'
            val2, digits2 = self.match_number()
            # Calculate concatenation of numbers from num_val to val2
            return self.calculate_range(num_val, val2, num_digits, digits2)
        elif self.pos < self.length and self.s[self.pos] == '(':
            self.pos += 1  # consume '('
            expr_val, expr_digits = self.parse()
            self.pos += 1  # consume ')'
            return self.calculate_repeat(num_val, expr_val, expr_digits)
        else:
            return num_val, num_digits

    def match_number(self):
        """Match and parse a number, return (value, digit_count)."""
        start = self.pos
        while self.pos < self.length and self.s[self.pos].isdigit():
            self.pos += 1
        if self.pos == start:
            return None, 0
        return int(self.s[start:self.pos]), self.pos - start

    def calculate_range(self, l_val, r_val, l_digits, r_digits):
        """Compute concatenation of all numbers from l to r."""
        MOD = 10**9 + 7
        result = 0
        start_digits = l_digits

        if start_digits == r_digits:
            # Same digit length throughout
            return self._range_concat_same_len(l_val, r_val, start_digits)
        else:
            # Different digit lengths possible
            result = 0
            curr = l_val
            while curr <= r_val:
                if len(str(curr)) == start_digits:
                    result = (result * pow(10, start_digits, MOD) + curr) % MOD
                else:
                    result = (result * pow(10, len(str(curr)), MOD) + curr) % MOD
                curr += 1
            return result

    def calculate_repeat(self, n_val, expr_val, expr_digits):
        """Compute expr repeated n_val times."""
        MOD = 10**9 + 7
        result = 0
        for _ in range(n_val):
            result = (result * pow(10, expr_digits, MOD) + expr_val) % MOD
        return result

def solution(s):
    """Main solution function."""
    if not s.strip():
        return "0\n"
    parser = ExpressionParser(s)
    val, digits = parser.parse()
    return str(val) + "\n"
