            if j > m or i > n:
                continue

            for k in range(vul):
                if dp[i][j][k] == -1:
                    continue

                curr = dp[i][j][k]

                # Option 1: Skip s1[i] (if i < n) - virus state unchanged
                if i < n:
                    if dp[i+1][j][k] < curr:
                        dp[i+1][j][k] = curr
                        parent[i+1][j][k] = '0'

                # Option 2: Skip s2[j] (if j < m) - virus state unchanged
                if j < m:
                    if dp[i][j+1][k] < curr:
                        dp[i][j+1][k] = curr
                        parent[i][j+1][k] = '1'

                # Option 3: Match s1[i] and s2[j] (if i < n and j < m)
                if i < n and j < m:
                    if s1[i] == s2[j]:
                        c_code = ord(s1[i]) - ord('A')
                        new_k = transition[k][c_code]
                        if new_k < vul:  # Don't complete the virus
                            if dp[i+1][j+1][new_k] < curr + 1:
                                dp[i+1][j+1][new_k] = curr + 1
                                parent[i+1][j+1][new_k] = '2'

    # Find maximum length across all final states
    max_len = 0
    best_k = 0
    for k in range(vul):
        if dp[n][m][k] > max_len:
            max_len = dp[n][m][k]
            best_k = k

    if max_len <= 0:
        return "0"

    # Reconstruct solution
    i, j, k = n, m, best_k
    result = []
    while i > 0 or j > 0:
        choice = parent[i][j][k]
        if choice == '2':
            result.append(s1[i-1])
            i -= 1
            j -= 1
            if i >= 0:
                c_code = ord(s1[i]) - ord('A')
                k = transition[k - 1][c_code] if k > 0 else 0
        elif choice == '0':
            i -= 1
        elif choice == '1':
            j -= 1
        else:
            break

    return "".join(result[::-1])

