from collections import deque

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "1 2 3 4"

    first_line = lines[0].split()
    n, m = int(first_line[0]), int(first_line[1])

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for i in range(1, len(lines)):
        parts = lines[i].split()
        if len(parts) >= 2:
            u, v = int(parts[0]), int(parts[1])
            adj[u].append(v)

    # Compute all-pairs shortest paths using BFS from each node
    dist = [[float('inf')] * (n + 1) for _ in range(n + 1)]
    for start in range(1, n + 1):
        dist[start][start] = 0
        queue = deque([start])
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if dist[start][v] == float('inf'):
                    dist[start][v] = dist[start][u] + 1
                    queue.append(v)

    # Precompute top 3 best starting cities for each destination
    # top_start[b] = list of (distance, start_city) sorted by distance descending
    top_start = [[] for _ in range(n + 1)]
    for b in range(1, n + 1):
        candidates = []
        for a in range(1, n + 1):
            if a != b and dist[a][b] != float('inf'):
                candidates.append((dist[a][b], a))
        candidates.sort(key=lambda x: x[0], reverse=True)
        top_start[b] = candidates[:3]

    # Precompute top 3 best ending cities for each source
    # top_end[c] = list of (distance, end_city) sorted by distance descending
    top_end = [[] for _ in range(n + 1)]
    for c in range(1, n + 1):
        candidates = []
        for d in range(1, n + 1):
            if c != d and dist[c][d] != float('inf'):
                candidates.append((dist[c][d], d))
        candidates.sort(key=lambda x: x[0], reverse=True)
        top_end[c] = candidates[:3]

    # Find the best 4-city path with order [a -> b -> c -> d]
    max_dist = -1
    best_order = None

    for b in range(1, n + 1):
        for c in range(1, n + 1):
            if b == c:
                continue
            if dist[b][c] == float('inf'):
                continue

            for da, a in top_start[b]:
                for dc, d in top_end[c]:
                    # Check all cities are different
                    if len({a, b, c, d}) == 4:
                        total = da + dist[b][c] + dc
                        if total > max_dist:
                            max_dist = total
                            best_order = (a, b, c, d)

    # Since problem guarantees a solution exists
    return " ".join(map(str, best_order if best_order else (1, 2, 3, 4)))


