        # Winning condition: at least threshold and lead by at least 2
        if a >= threshold and a >= b + 2:
            return True
        if b >= threshold and b >= a + 2:
            return True

        # Special case: if one reaches threshold where other is threshold-1
        # The set continues until 2-point margin
        if a == threshold and b == threshold - 1 if threshold >= 25 else (a == threshold and b == threshold - 1):
            return True

        return False

    for i in range(1, len(lines)):
        if i >= len(lines):
