def find_best_score(a, b):
    """Find best match score for given total points"""

    # Try all possible match outcomes, best first
    candidates = []
    for a_w in [3, 2, 1, 0]:
        for b_w in [0, 1, 2, 3]:
            if a_w + b_w > 5:
                continue
            if a_w == 3 and b_w >= 3:
                continue
            if b_w == 3 and a_w >= 3:
                continue
            if a_w < 3 and b_w < 3 and a_w + b_w < 3:
                continue
            candidates.append((a_w, b_w, a_w - b_w))

    # Sort by preference: minimize sets, maximize diff
    candidates.sort(key=lambda x: (x[0] + x[1], x[0] - b_w, x[0] - b_w))

    for a_w, b_w, diff in candidates:
        if generate_sets_for_match(a, b, a_w, b_w):
            result = format_output(a_w, b_w)
            return format_output(a_w, b_w)


def generate_sets_for_match(total_a, total_b, a_wins, b_wins):
    """Generate valid set scores for a given win pattern"""

    if a_wins + b_wins == 0 or a_wins + b_wins == 1 and (a_wins == 0 or b_wins == 0):
        return None

    possible_sets = []
    for da in range(28):
        for db in range(28):
            if is_valid_set(da, db):
                possible_sets.append((da, db))

    # DFS to find valid combination
    total_n = a_wins + b_wins
    pattern = ['a'] * a_wins + ['b'] * b_wins

    target_a = total_a
    target_b = total_b

    result = backtrack(possible_sets, pattern, target_a, target_b, 0, [])
    if result:
        return result
    return None


def backtrack(possible_sets, pattern, target_a, target_b, idx, current):
    if idx == len(pattern):
        sa = sum(x[0] for x in current)
        sb = sum(x[1] for x in current)
        return (sa, sb) == (target_a, target_b) and (sa, sb)

    return backtrack(possible_sets, pattern, target_a, target_b, idx + 1, current + [possible_sets[idx]])


def is_valid_set(a, b):
    """Check if (a,b) can be a valid set ending with these scores"""
    if a >= 25 and a >= b + 2:
        return True
    if b >= 25 and b >= a + 2:
