def solution(input_str):
    # Parse input
    lines = input_str.strip().split('\n')
    if not lines:
        return ""
    n, m = map(int, lines[0].split())

    edges = []
    for i in range(m):
        parts = lines[1+i].split()
        if len(parts) >= 2:
            u, v = int(parts[0]), int(parts[1])
            edges.append((u, v))

    def are_crossing(u1, v1, u2, v2, n):
        def normalize(x):
            return (x - 1) % n

        a1, a2, b1, b2 = normalize(u1), normalize(v1), normalize(u2), normalize(v2)

        # Edges cross if vertices appear in alternating order around the circle
        # Check both directions of arc between endpoints

        def between(start, end, point):
            # Is point strictly between start and end (clockwise)?
            return (point - start + n) % n < (end - start + n) % n

        # Edge (u1,v1) splits circle into two arcs
        # Edge (u2,v2) crosses if both endpoints of u2,v2 are in different arcs

        # Check if a2 is between a1 and b1 AND a2 is NOT between b1 and a1
        between_ab = between(a1, b1, a2)
        between_ba = between(b1, a2)

        # Points must be in different arcs
        return (between_ab and not between_ba) or (not between_ab and between_ba)

    # Build conflict graph: edges can't both go inside OR both go outside if they cross
    adj = [[] for _ in range(m)]
    possible = True
    colors = {}  # 0 for inside, 1 for outside

    def dfs(u, c):
        colors[u] = c
        for v in adj[u]:
            if v not in colors:
                if not dfs(v, 1 - c):
                    return False
            elif colors[v] == c:
                return False
        return True

    for i in range(m):
        if i not in colors:
            if not dfs(i, 0):
                possible = False
                break

    if not possible:
        return "Impossible"

    # Output result
    return ''.join('i' if i in colors and colors[i] == 0 else 'o' for i in range(m))
