4. When strings don't share characters, we can concatenate them in lexicographic order for the smallest result

```python
def solution(s):
    lines = s.strip().split('\n')
    if not lines:
        return "NO\n"

    n = int(lines[0])
    if len(lines) < n + 1:
        return "NO\n"

    target_strs = lines[1:n+1]

    # Check if any string is a substring of another
    for i in range(n):
        for j in range(n):
            if i != j and target_strs[j] in target_strs[i]:
                return "NO\n"

    # Track which strings use which characters
    # Each character can only appear in one target string
    char_to_string_index = {}
    for idx, st in enumerate(target_strs):
        for c in st:
            if c in char_to_string_index and char_to_string_index[c] != idx:
                # Character c appears in multiple different strings
                return "NO\n"
            char_to_string_index[c] = idx

    # All valid - sort lexicographically and concatenate
    return ''.join(sorted(target_strs)) + "\n"
