                    queue.append(v)

        return dist, parent

    def get_path(start, end):
        dist, parent = bfs(start)
        path = []
        curr = end
        while curr != start:
            path.append(curr)
            curr = parent[curr]
        path.append(start)
        return path[::-1]

    best_score = -1
