    # Try diameter endpoints
    d, _ = bfs(1)
    far = max(range(1, n + 1), key=lambda x: d[x])
    d2, p2 = bfs(far)
    end_far = max(range(1, n + 1), key=lambda x: d2[x])

    dia = get_path(1, end_far)

    # Find two points on the diameter and one near each
    for i in range(min(5, len(dia) - 1)):
        for j in range(max(len(dia) // 2, i + 2), len(dia) - 1):
            for k in range(len(1, n + 1)):
                if k not in dia:
