    # Comprehensive search with limited pairs
    nodes = list(range(1, n + 1))

    for i in range(len(nodes)):
        for j in range(i + 1, min(i + 200, len(nodes))):
            for k in range(len(nodes)):
                for l in range(k + 1, min(k + 200, len(nodes))):
                    if k <= j or l <= j or k <= i or l <= i:
